import { pgTable, uuid, text, timestamp, integer, numeric, pgEnum, unique, index } from 'drizzle-orm/pg-core'
import { user } from './auth-schema'

/**
 * Application tables.
 *
 * `user`, `session`, `account` and `verification` are Better Auth's and live in
 * auth-schema.ts, generated by its CLI (`npx @better-auth/cli generate`) — do not
 * hand-edit that file; change the `user.additionalFields` config in src/lib/auth.ts
 * and regenerate. Everything Better Auth does not own belongs here.
 *
 * Two conventions from structure.md apply: tables are snake_case plural, and Drizzle
 * fields are camelCase mapping onto snake_case columns.
 *
 * PostGIS columns (zones.geometry) have no native Drizzle type and are added by a raw
 * SQL migration instead, then read and written through `sql` templates (ADR-011).
 * Zones arrive with the zone endpoints.
 */

export * from './auth-schema'

export const planEnum = pgEnum('plan', ['free', 'standard', 'premium'])

/**
 * The tenant. Every resource belongs to a workspace, never directly to a user.
 *
 * Before this existed, `zones.user_id` meant an invited collaborator could not see
 * anything their team had created — the Team screen could list members but sharing
 * was structurally impossible. Plan limits are a workspace property too: seats, zones
 * and daily captures are what the *account* bought, not what each person gets.
 *
 * Every user gets a personal workspace on first sign-in, so "no team" is just a
 * workspace with one member rather than a separate code path.
 */
export const workspaces = pgTable('workspaces', {
  id: uuid('id').primaryKey().defaultRandom(),
  name: text('name').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})

/** Workspace-scoped role. Distinct from `user.role`, which is platform-wide (BR-027). */
export const memberRoleEnum = pgEnum('member_role', ['owner', 'editor', 'viewer'])

export const memberStatusEnum = pgEnum('member_status', ['active', 'invited'])

export const workspaceMembers = pgTable(
  'workspace_members',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),

    /**
     * Null while an invitation is outstanding: someone can be invited by email
     * before they have an account. It is filled in when they sign up or sign in
     * with that address.
     */
    userId: text('user_id').references(() => user.id, { onDelete: 'cascade' }),

    /** Always present — it is what an invitation is addressed to. */
    email: text('email').notNull(),
    role: memberRoleEnum('role').notNull().default('viewer'),
    status: memberStatusEnum('status').notNull().default('invited'),

    invitedAt: timestamp('invited_at', { withTimezone: true }).notNull().defaultNow(),
    joinedAt: timestamp('joined_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('workspace_members_workspace_id_idx').on(t.workspaceId),
    index('workspace_members_user_id_idx').on(t.userId),
    // Case-insensitive uniqueness per workspace is enforced by a functional index in
    // the raw SQL migration — Drizzle cannot express lower(email) here.
  ],
)

export const workspacePlans = pgTable(
  'workspace_plans',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    plan: planEnum('plan').notNull().default('free'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
    /** NULL = active indefinitely. Billing is not implemented; plans are assigned manually. */
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique('workspace_plans_workspace_id_unique').on(t.workspaceId),
    index('workspace_plans_workspace_id_idx').on(t.workspaceId),
  ],
)

/**
 * Which workspace a user is currently looking at.
 *
 * Deliberately its own table rather than a column on Better Auth's `user`: that file
 * is regenerated by its CLI, which would silently drop anything added there. Keeping
 * our columns out of it means a regeneration costs only re-applying `withTimezone`.
 *
 * Null active workspace resolves to the user's personal one.
 */
export const userPreferences = pgTable('user_preferences', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  activeWorkspaceId: uuid('active_workspace_id').references(() => workspaces.id, { onDelete: 'set null' }),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})

export type UserPreferenceRow = typeof userPreferences.$inferSelect
export type WorkspaceRow = typeof workspaces.$inferSelect
export type WorkspaceMemberRow = typeof workspaceMembers.$inferSelect
export type WorkspacePlanRow = typeof workspacePlans.$inferSelect

/** BR-020: chosen when the zone is created, and editable afterwards per BR-029. */
export const roadClassEnum = pgEnum('road_class', ['nasional', 'nasional_provinsi', 'semua'])

/** Whether the zone's capture windows are running. */
export const zoneStatusEnum = pgEnum('zone_status', ['collecting', 'paused'])

export const zones = pgTable(
  'zones',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /**
     * Attribution only — who drew this. Never used for access control; that is the
     * workspace's job. Nullable so a zone survives the person who made it leaving.
     */
    createdBy: text('created_by').references(() => user.id, { onDelete: 'set null' }),
    name: text('name').notNull(),
    roadClass: roadClassEnum('road_class').notNull(),
    status: zoneStatusEnum('status').notNull().default('collecting'),

    // `geometry geometry(Polygon, 4326)` is added by migration 0002 — PostGIS has no
    // native Drizzle type, so it is written and read through `sql` templates with
    // ST_GeomFromGeoJSON / ST_AsGeoJSON (ADR-011). Declaring it here would make
    // drizzle-kit try to drop it on the next generate.

    /**
     * Segment count and total length inside the boundary for this road class.
     *
     * Nullable on purpose: they are derived from HERE, so an unconfigured HERE key
     * means "not known yet", which the UI renders as "—". Storing 0 would claim the
     * zone matched no roads, which is a different and wrong statement.
     */
    roadsCount: integer('roads_count'),
    lengthKm: numeric('length_km', { precision: 10, scale: 2 }),

    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // BR-015 — zone names are unique per workspace now, not per user. Two people on
    // the same team creating "Zona Malioboro" is the collision that matters.
    // BR-015 — zone names are unique per workspace now, not per user. Two people on
    // the same team creating "Zona Malioboro" is the collision that matters.
    unique('zones_workspace_id_name_unique').on(t.workspaceId, t.name),
    index('zones_workspace_id_idx').on(t.workspaceId),
  ],
)

export type ZoneRow = typeof zones.$inferSelect

/**
 * A capture window (F-05/F-06), stored as the UI models it rather than as cron.
 *
 * ADR: the spec said `cron_expr`, but the Schedule board edits start/end time, an
 * interval and weekdays. Window → cron is deterministic; cron → window is not, since
 * most cron expressions have no window form. So the window is stored and the cron
 * expression is derived when the scheduler loads it — the lossy direction is the one
 * that happens in memory, never in the database.
 */
export const captureIntervalEnum = pgEnum('capture_interval', ['15min', 'hourly', 'daily'])

export const scheduleStatusEnum = pgEnum('schedule_status', ['active', 'paused', 'deleted'])

export const schedules = pgTable(
  'schedules',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    zoneId: uuid('zone_id')
      .notNull()
      .references(() => zones.id, { onDelete: 'cascade' }),
    createdBy: text('created_by').references(() => user.id, { onDelete: 'set null' }),

    label: text('label').notNull(),
    /** "HH:mm" in Asia/Jakarta — the window the UI draws on the hour ruler. */
    startTime: text('start_time').notNull(),
    endTime: text('end_time').notNull(),
    interval: captureIntervalEnum('interval').notNull(),
    /** ISO weekday numbers the UI uses: 0 = Monday … 6 = Sunday. */
    days: integer('days').array().notNull(),

    /**
     * `deleted` is a soft delete (F-06) — capture history references the schedule
     * that produced each frame, so removing the row would orphan that history.
     */
    status: scheduleStatusEnum('status').notNull().default('active'),

    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('schedules_workspace_id_idx').on(t.workspaceId),
    index('schedules_zone_id_idx').on(t.zoneId),
    // BR-005 counts only `active` rows, so the status is part of the lookup.
    index('schedules_workspace_status_idx').on(t.workspaceId, t.status),
  ],
)

export type ScheduleRow = typeof schedules.$inferSelect
